# AUTO-GENERATED by Claude Code
# Purpose: guards the rule that every widget is drawn in the one shared frame
#          (services/ui/ui/render.py, widget_frame; spec/services/ui/README.md, "Widgets: three
#          regions"): a widget supplies its parts and can't draw a bar, an Inputs panel or a
#          bottom line of its own.
# Usage: uv run pytest tests/services/ui/test_widget_frame.py
# ---------------------------------------------------------------------------
from __future__ import annotations

import ast
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parents[3] / "services" / "ui"))

from ui import render
from ui.widgets import WIDGETS

SOURCE = Path(render.__file__).read_text(encoding="utf-8")
TREE = ast.parse(SOURCE)
# drawn by the frame only, and where each may be called
FRAME_ONLY = {
    "widget_bar": {"widget_frame"},
    "widget_line": {"widget_frame"},
    "form_section": {"widget_frame"},
    "float_button": {"widget_bar"},
    "close_view_button": {"widget_bar"},
    "ai_toggle": {"widget_bar"},
    "form_toggle": {"widget_bar"},
    "strip_ask_box": {"widget_bar"},
    "widget_frame": {"render_component"},
}
# a widget that is shown as another kind's view (its row in WIDGETS has no view of its own)
SHOWN_AS = {"config": ("tool", "fields")}


def calls_by_function() -> dict[str, set[str]]:
    """The name of every function called, by the top-level function it is called in."""
    found: dict[str, set[str]] = {}
    for node in TREE.body:
        if isinstance(node, ast.FunctionDef):
            found[node.name] = {
                call.func.id
                for call in ast.walk(node)
                if isinstance(call, ast.Call) and isinstance(call.func, ast.Name)
            }
    return found


def test_only_the_frame_draws_a_bar_an_inputs_panel_or_a_bottom_line() -> None:
    for function, called in calls_by_function().items():
        for name, allowed in FRAME_ONLY.items():
            hint = f"{function}() calls {name}(): only {sorted(allowed)} may (a widget returns WidgetParts)"
            assert name not in called or function in allowed, hint


def test_every_widget_kind_has_parts() -> None:
    kinds = {widget.kind for widget in WIDGETS} - set(SHOWN_AS)
    assert kinds == set(render.PARTS), "a widget kind needs a row in render.PARTS (and widgets.WIDGETS)"
    for shown in SHOWN_AS.values():
        assert set(shown) <= set(render.PARTS)


def test_every_view_kind_is_drawn_by_the_frame() -> None:
    made = {
        keyword.value.value
        for call in ast.walk(TREE)
        if isinstance(call, ast.Call) and isinstance(call.func, ast.Name) and call.func.id == "View"
        for keyword in call.keywords
        if keyword.arg == "kind" and isinstance(keyword.value, ast.Constant)
    }
    assert made <= set(render.PARTS)


def test_a_parts_function_returns_widget_parts() -> None:
    functions = {node.name: node for node in TREE.body if isinstance(node, ast.FunctionDef)}
    for make in render.PARTS.values():
        returns = functions[make.__name__].returns
        assert isinstance(returns, ast.Name), make.__name__
        assert returns.id == "WidgetParts", make.__name__


def test_the_bar_holds_only_its_five_things() -> None:
    bar = next(node for node in TREE.body if isinstance(node, ast.FunctionDef) and node.name == "widget_bar")
    called = {call.func.id for call in ast.walk(bar) if isinstance(call, ast.Call) and isinstance(call.func, ast.Name)}
    # the name (type_label), the Ask AI box, the AI button, Inputs, float, close: nothing else
    assert called == {"type_label", "strip_ask_box", "ai_toggle", "form_toggle", "float_button", "close_view_button"}
